commands:
mkdir -p /tmp/tlscheck && cd /tmp/tlscheck && kubectl get secret mongodb-tls -n test-social-network -o jsonpath='{.data.tls\.pem}' | base64 -d > tls.pem && kubectl get secret mongodb-tls -n test-social-network -o jsonpath='{.data.ca\.crt}' | base64 -d > ca.crt && which python3 && python3 -I -c "
import ssl,sys
for f in ['tls.pem','ca.crt']:
    try:
        d=ssl._ssl._test_decode_cert('/tmp/tlscheck/'+f)
        print(f, d['subject'], d['issuer'], d['notBefore'], d['notAfter'])
    except Exception as e: print(f,'ERR',e)
"; date -u; grep -c 'BEGIN' tls.pem; grep BEGIN tls.pem
